export function getEbookContent(id: string): EbookContent | null {
  return EBOOK_CATALOG[id] ?? null;
}

export function listEbookMeta() {
  return Object.values(EBOOK_CATALOG).map(({ id, title, category, isPremium, price, pages }) => ({
    id, title, category, isPremium, price, pages,
  }));
}
